package palindrome

import (
	"errors"
	"fmt"
)

// Product represents a palindromic number and its factorizations.
type Product struct {
	Value          int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic products of two
// numbers within the inclusive range [fmin, fmax], along with all factor
// pairs for each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var min, max Product
	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if !isPalindrome(product) {
				continue
			}
			switch {
			case len(min.Factorizations) == 0 || product < min.Value:
				min = Product{product, [][2]int{{i, j}}}
			case product == min.Value:
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
			switch {
			case len(max.Factorizations) == 0 || product > max.Value:
				max = Product{product, [][2]int{{i, j}}}
			case product == max.Value:
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
		}
	}

	if len(max.Factorizations) == 0 {
		return Product{}, Product{}, errors.New("no palindromes found")
	}
	return min, max, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
func isPalindrome(n int) bool {
	s := fmt.Sprintf("%d", n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}

